import { BalanceStatus } from '../../shared/types';

export interface Balance {
  id: string;
  employeeId: string;
  leaveType: string;
  totalEntitlement: number;
  usedDays: number;
  remainingDays: number;
  fiscalYear: number;
  status: BalanceStatus;
  createdAt: Date;
  updatedAt: Date;
}

export class InsufficientBalanceError extends Error {
  public readonly code = 'INSUFFICIENT_BALANCE';

  constructor(message: string) {
    super(message);
    this.name = 'InsufficientBalanceError';
  }
}

export class BalanceNotFoundError extends Error {
  public readonly code = 'NOT_FOUND';

  constructor(message: string) {
    super(message);
    this.name = 'BalanceNotFoundError';
  }
}

export interface IBalanceRepository {
  findByEmployeeId(employeeId: string): Promise<Balance[]>;
  findByEmployeeIdAndLeaveType(employeeId: string, leaveType: string): Promise<Balance | null>;
  findByEmployeeIdAndFiscalYear(employeeId: string, fiscalYear: number): Promise<Balance[]>;
  create(balance: Omit<Balance, 'id' | 'createdAt' | 'updatedAt'>): Promise<Balance>;
  update(id: string, data: Partial<Balance>): Promise<Balance | null>;
  deductDays(id: string, days: number): Promise<Balance | null>;
}

export interface IBalanceService {
  getBalance(employeeId: string, leaveType: string): Promise<Balance | null>;
  getBalances(employeeId: string): Promise<Balance[]>;
  hasSufficientBalance(employeeId: string, leaveType: string, requestedDays: number): Promise<boolean>;
  deductBalance(employeeId: string, leaveType: string, days: number): Promise<Balance>;
}

export interface AuditLog {
  id: string;
  entityType: string;
  entityId: string;
  action: string;
  performedBy: string;
  changes: Record<string, unknown>;
  createdAt: Date;
}

export class AuditLogValidationError extends Error {
  public readonly code = 'VALIDATION_ERROR';

  constructor(message: string) {
    super(message);
    this.name = 'AuditLogValidationError';
  }
}

export interface IAuditLogRepository {
  findByEntity(entityType: string, entityId: string): Promise<AuditLog[]>;
  create(entry: Omit<AuditLog, 'id' | 'createdAt'>): Promise<AuditLog>;
  findAll(filters?: { entityType?: string; performedBy?: string; fromDate?: Date; toDate?: Date }): Promise<AuditLog[]>;
}

import { Pool } from 'pg';
import dotenv from 'dotenv';

dotenv.config();

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true, ca: process.env.DB_SSL_CA }
      : false
});

import Fastify from 'fastify';
import { uptimeRoutes } from './modules/uptime/uptime.routes';

const app = Fastify({ logger: true });

app.register(uptimeRoutes);

export default app;

export enum LeaveType {
  annual = 'annual',
  sick = 'sick',
  emergency = 'emergency',
}

export enum LeaveStatus {
  draft = 'draft',
  submitted = 'submitted',
  approved = 'approved',
  rejected = 'rejected',
  cancelled = 'cancelled',
}

export enum EmploymentStatus {
  active = 'active',
  inactive = 'inactive',
  terminated = 'terminated',
}

export enum BalanceStatus {
  active = 'active',
  exhausted = 'exhausted',
}

export enum NotificationType {
  leave_submitted = 'leave_submitted',
  leave_approved = 'leave_approved',
  leave_rejected = 'leave_rejected',
  leave_cancelled = 'leave_cancelled',
}

export enum NotificationStatus {
  pending = 'pending',
  sent = 'sent',
  read = 'read',
  archived = 'archived',
}

{
  "name": "trackeros",
  "version": "0.1.0",
  "tier": "tier1",
  "templateId": "corporate-ops-web-mobile",
  "description": "Trackeros — a corporate operations web and mobile platform for\n  mid-sized companies. Provides employee self-service (leave\n  requests, balances, expense claims), manager workflows\n  (approvals, team views, time-off calendars), and HR admin\n  surfaces (leave policy configuration, balance accruals,\n  audit reports).\n  \n  Backend: TypeScript on Node 20 (Fastify), PostgreSQL via\n  Knex migrations + a thin repository layer, BullMQ for\n  background jobs (accrual schedulers, notification fanout).\n  Module structure: src/modules/<name>/<name>.{model,\n  repository,service,controller,routes}.ts. Domain modules\n  include leave, balance, employee, policy, notification.\n  Shared utilities under src/shared/ (db connection, base\n  repository, error types).\n  \n  Frontend: React + Vite SPA for the web client, React Native\n  for the mobile client (shared @trackeros/contracts package\n  for the typed REST surface). Auth via JWT against the\n  backend's /auth endpoints; identity comes from corporate\n  OIDC in production and from local users in development.\n  \n  Tests: Jest for unit + integration. CI on GitHub Actions\n  runs lint (ESLint) + typecheck (tsc --noEmit) + unit tests +\n  a Semgrep security pass on every PR. Conventional Commits +\n  squash-merge. Strict TypeScript (no implicit any, strict\n  null checks).",
  "stack": {
    "language": "TypeScript",
    "nodeVersion": "20",
    "packageManager": "npm",
    "testFramework": "Jest",
    "framework": "Fastify",
    "frontend": "React Native",
    "database": "PostgreSQL",
    "architectureStyle": "modular-monolith"
  },
  "adapters": {
    "database": {
      "type": "postgres",
      "configKey": "DATABASE_URL"
    },
    "queue": {
      "type": "bullmq",
      "configKey": "REDIS_URL"
    },
    "llm": {
      "type": "azure-openai",
      "configKey": "LLM_BASE_URL"
    }
  },
  "_comment_gate": "CI (build/tests/lint/security) runs first via pipeline.adapter. The Gestalt LLM gate (constraint-agent + review-agent) runs after CI passes as a pre-merge architectural review.",
  "qualityGate": {
    "required": [
      "constraint-check",
      "design-review"
    ],
    "blockingSignals": [
      "GOLDEN_PRINCIPLE_BREACH",
      "CONSTRAINT_VIOLATION"
    ],
    "autoResolvableSignals": [
      "LINT_FAILURE",
      "TEST_FAILURE"
    ],
    "maxRetries": 3
  },
  "constraints": {
    "rules": [
      {
        "id": "no-any",
        "description": "Use unknown with type guards instead of any",
        "severity": "high"
      },
      {
        "id": "no-direct-db-outside-repository",
        "description": "Database calls must go through repository pattern",
        "severity": "critical"
      },
      {
        "id": "no-hardcoded-secrets",
        "description": "No hardcoded passwords, API keys, or tokens",
        "severity": "critical"
      },
      {
        "id": "no-gestalt-internal-deps",
        "description": "Do not add @gestalt/* packages as project dependencies — these are Gestalt platform internals not available on npm",
        "severity": "critical"
      }
    ]
  },
  "codeGeneration": {
    "backend": "aider",
    "verification": {
      "buildCmd": "",
      "testCmd": "find src -name '*.ts' -not -name '*.spec.ts' -not -name '*.test.ts' -not -name '*.d.ts' -type f | grep -q . && npm run build && npx jest --passWithNoTests",
      "lintCmd": ""
    }
  },
  "_comment_verification": "MECHANICAL COMPILE GATE: run in the code-agent work dir before commit; a non-zero exit blocks the commit + routes to self-heal so a compile/type error never reaches CI. Installs deps (clones carry no node_modules), guards on source presence so an empty phase exits 0.",
  "verification": {
    "command": "npm install --include=dev --no-audit --no-fund && if find src -name '*.ts' -not -name '*.spec.ts' -not -name '*.test.ts' -not -name '*.d.ts' -type f | grep -q .; then npm run build && npx jest --passWithNoTests; else echo 'no source files to verify'; fi",
    "timeoutSeconds": 900
  },
  "pipeline": {
    "adapter": "github-actions",
    "autoMerge": true,
    "mergeMethod": "squash"
  },
  "prAgent": {
    "enabled": true,
    "blockOnChangesRequested": true,
    "pendingTimeoutSeconds": 90
  },
  "planner": {
    "enabled": true,
    "maxPhasesPerFeature": 10,
    "maxFilesPerPhase": 5,
    "architectureReviewPerPhase": true,
    "maxPhaseRetries": 2,
    "engine": "langgraph"
  },
  "tokenManagement": {
    "promptCompressionThreshold": 6000,
    "maxRetryBudgetMultiplier": 2.0,
    "enableDynamicBudget": true,
    "enableScopeReduction": true
  },
  "maintenance": {
    "driftCheck": {
      "enabled": true,
      "scheduleUtc": "0 2 * * *"
    },
    "alignmentCheck": {
      "enabled": true,
      "scheduleUtc": "0 3 * * *"
    },
    "gcCheck": {
      "enabled": true,
      "scheduleUtc": "0 4 * * 5"
    },
    "monitoring": {
      "adapter": "noop",
      "enabled": true,
      "connectionConfig": {},
      "thresholds": {
        "errorRatePercent": 5.0,
        "latencyP99Ms": 2000,
        "alertCountWindow": "1h",
        "alertCountThreshold": 10
      }
    }
  },
  "identity": {
    "providers": [
      {
        "type": "local",
        "enabled": true,
        "warningBanner": true,
        "allowedInProduction": false
      }
    ],
    "roleMapping": [],
    "defaultRole": null,
    "sessionTtlMinutes": 480
  }
}
